mapper.select:
SELECT a.*,c.club_name,s.stu_name AS apply_stu_name FROM club_dissolve_apply a JOIN club c ON c.club_id=a.club_id JOIN student s ON s.stu_id=a.apply_stu_id WHERE 1=1
AND a.union_audit_status='pending' AND a.final_status='pending'
AND c.tea_id=#{userId}
AND a.club_id=#{clubId}
ORDER BY a.apply_time DESC,a.dissolve_apply_id DESC
